  "A road trip through fishing villages and fjords with a rorbu cabin every night and the sea at the doorstep.": "Balıkçı köyleri ve fiyortlardan geçen bir yolculuk; her gece bir rorbu kulübesi, kapının önünde deniz.",
  "A room for the mind — the best investment in the house.": "Zihne ayrılmış bir oda — evin en iyi yatırımı.",
  "A short pre-work session that empties mental clutter and sets a single, sharp intention before deep work.": "Zihinsel dağınıklığı temizleyen, derin çalışmadan önce tek ve net bir niyet belirleyen kısa hazırlık seansı.",
  "A short rationale to reinforce motivation during resistance.": "Dirençle karşılaştığında motivasyonunu güçlendirecek kısa bir gerekçe.",
  "A single completed micro-task creates more neurological momentum than ten master outlines.": "Tamamlanan tek bir mikro görev, on kapsamlı plandan daha fazla nörolojik ivme yaratır.",
  "A skill that opens the other 70% of the planet.": "Gezegenin kalan %70'ini açan bir beceri.",
  "A skippered week among the Dalmatian islands — anchor in a new cove every night.": "Dalmaçya adalarında kaptanlı bir hafta — her gece yeni bir koyda demirle.",
  "A slow body scan that releases tension from head to toe and settles the nervous system.": "Baştan ayağa gerginliği bıraktıran, sinir sistemini sakinleştiren yavaş bir beden taraması.",
  "A slower, richer, more generous life.": "Daha yavaş, daha zengin, daha cömert bir hayat.",
  "A small, daily reminder that you keep your word.": "Sözünü tuttuğunu hatırlatan küçük, günlük bir işaret.",
  "A soft, slow session that reviews the day with kindness and guides the body toward deep sleep.": "Günü şefkatle değerlendiren ve bedeni derin uykuya hazırlayan yumuşak, yavaş bir seans.",
  "A space so quiet it does the thinking with you.": "Seninle birlikte düşünecek kadar sessiz bir alan.",
  "A super-jeep chase for the northern lights, glacier caves, and hot springs under the snow.": "Kuzey ışıklarını, buzul mağaralarını ve kar altındaki kaplıcaları keşfetmek için süper jip yolculuğu.",
  "A tiny cabin among trees with a desk, a stove and no signal — where the book gets written.": "Ağaçlar arasında masa ve sobası olan, telefon çekmeyen küçük bir kulübe — kitabın yazıldığı yer.",
  "A tool for keeping promises.": "Sözlerini tutmanı sağlayan bir araç.",
  "A twelve-course tasting menu at a three-star restaurant with wine pairing.": "Üç yıldızlı bir restoranda şarap eşleşmeli on iki aşamalı tadım menüsü.",
  "A used but sound 30-footer: sleeps four, coastal cruising, weekends that cost only wind.": "Kullanılmış ama sağlam bir 30 ft tekne: dört kişilik yatak, kıyı seyri, bedeli yalnızca rüzgâr olan hafta sonları.",
  "A vivid visualization of your future self and your dream life, so your daily decisions start pointing there.": "Günlük kararlarını o yöne çevirmek için gelecekteki benliğini ve hayalindeki hayatı canlı biçimde gözünde canlandır.",
  "A warm, uplifting session that raises your mood through breath, memory and a gentle inner smile.": "Nefes, anılar ve içten gelen hafif bir gülümsemeyle ruh halini yükselten sıcak, canlandırıcı bir seans.",
  "A week in Positano with a private boat to Capri, lemon groves, and dinner on the water.": "Positano'da bir hafta; Capri'ye özel tekne, limon bahçeleri ve su üstünde akşam yemeği.",
  "A week in a Left Bank apartment: markets, museums, long dinners and walks with no destination.": "Left Bank'te bir dairede bir hafta: pazarlar, müzeler, uzun akşam yemekleri ve hedefsiz yürüyüşler.",
  "A week in a high-floor hotel with a skyline view, Broadway, galleries and 5 a.m. runs along the river.": "Şehir manzaralı yüksek katlı bir otelde bir hafta; Broadway, galeriler ve sabah 5'te nehir boyunca koşular.",
  "A week on a crewed 30 m motor yacht: Monaco to Saint-Tropez with a chef, tender and toys.": "Mürettebatlı 30 m motor yatta bir hafta: şef, servis botu ve su oyuncaklarıyla Monaco'dan Saint-Tropez'ye.",
