  "Box Breathing (4-4-4-4): {state}": "Kutu Nefesi (4-4-4-4): {state}",
  "Box Breathing / Parasympathetic Reset": "Kutu Nefesi / Parasempatik Yenilenme",
  "Box breathing: inhale for 4 seconds, hold for 4, exhale for 4, and rest for 4.": "Kutu nefesi: 4 saniye nefes al, 4 saniye tut, 4 saniye ver ve 4 saniye dinlen.",
  "Brass Details": "Pirinç Detaylar",
  "Breaks initial inertia.": "Başlangıçtaki ataleti kırar.",
  "Breakthrough": "Atılım",
  "Breathe In": "Nefes Al",
  "Breathe Out": "Nefes Ver",
  "Breathe deeply and slowly. Confident people breathe slowly. Let your breath teach your body.": "Derin ve yavaş nefes al. Kendine güvenen insanlar yavaş nefes alır. Nefesin bedenine öğretsin.",
  "Breathe deeply. Approach your next task with calm, centered poise.": "Derin nefes al. Sıradaki işine sakin ve dengeli bir duruşla yaklaş.",
  "Breathe in for four. Out for six. Let the breathing slow down the mind.": "Dörde kadar sayarak al. Altıya kadar sayarak ver. Nefes zihnini yavaşlatsın.",
  "Breathe in for four... hold for four... and out for six. Slow the whole system down.": "Dörde kadar sayarak nefes al... dörde kadar tut... altıya kadar ver. Tüm sistemini yavaşlat.",
  "Breathe in gently... and let out a long, slow exhale. Let each breath be a little slower than the last.": "Yumuşakça nefes al... uzun ve yavaş bir nefes ver. Her nefes bir öncekinden biraz daha yavaş olsun.",
  "Breathe in joy. Breathe out heaviness. Breathe in lightness. Breathe out worry.": "Neşeyi içine çek. Ağırlığı bırak. Hafifliği içine çek. Kaygıyı bırak.",
  "Breathe in power. Breathe out excuses. Breathe in fire. Breathe out hesitation.": "Gücü içine çek. Bahaneleri bırak. Ateşi içine çek. Tereddüdü bırak.",
  "Breathe in strength. Breathe out doubt. One more time.": "Gücü içine çek. Şüpheyi bırak. Bir kez daha.",
  "Breathe in through your nose. Breathe out slowly. Let your weight sink downward, rooted and stable.": "Burnundan nefes al. Yavaşça ver. Ağırlığının aşağıya yerleştiğini hisset; köklü ve sağlam.",
  "Breathe in, and imagine the breath is light. Breathe out, and let that light spread through your chest.": "Nefes al ve nefesinin ışık olduğunu hayal et. Nefes ver ve bu ışığın göğsüne yayılmasına izin ver.",
  "Breathe in. Feel the stillness. Breathe out. Let the noise settle like dust in a quiet room.": "Nefes al. Dinginliği hisset. Nefes ver. Gürültü, sessiz bir odadaki toz gibi yere çöksün.",
  "Breathe in... and go. Now.": "Nefes al... ve başla. Şimdi.",
  "Breathe into that place. And as you exhale, imagine the story loosening, like an old rope untying.": "Nefesini o bölgeye yönlendir. Verirken hikâyenin eski bir ipin düğümü çözülür gibi gevşediğini hayal et.",
  "Breathe out the day. It's done. You showed up.": "Nefesinle günü bırak. Bitti. Sen oradaydın.",
  "Breathe slowly. In through the nose. Out through the mouth. Let the shoulders drop.": "Yavaş nefes al. Burundan al. Ağızdan ver. Omuzların düşsün.",
  "Breathe slowly. With each breath, thank your lungs, quietly, for doing this without being asked.": "Yavaş nefes al. Her nefeste, senden talimat beklemeden çalıştıkları için akciğerlerine içinden teşekkür et.",
  "Breathe slowly. With each exhale, let today loosen its grip. You are about to travel forward in time.": "Yavaş nefes al. Her verişte bugünün üzerindeki etkisi gevşesin. Birazdan zamanda ileriye gideceksin.",
  "Breathe. The mind is quiet. The task is clear. The body is ready.": "Nefes al. Zihin sessiz. Görev açık. Beden hazır.",
  "Breathe... and drift.": "Nefes al... ve kendini bırak.",
  "Breathing, meditation & mental space decluttering": "Nefes, meditasyon ve zihinsel alanı düzenleme",
  "Bridge \"{name}\" to a real savings and execution plan.": "\"{name}\" için gerçek bir birikim ve eylem planına köprü kur.",
  "Brief context on what belongs here.": "Buraya neyin ait olduğuna dair kısa açıklama.",
  "Bright red 1970s coupé, analog everything, pop-up joy.": "Parlak kırmızı 1970'ler kupesi; her şeyi analog, açılır farlarıyla neşe kaynağı.",
  "Bring to mind a moment when you felt truly good. A laugh. A sunrise. A hug. A win.": "Kendini gerçekten iyi hissettiğin bir anı hatırla. Bir kahkaha. Bir gün doğumu. Bir sarılma. Bir başarı.",
  "Bring to mind one doubt you carry. A sentence that starts with \"I can't\", or \"I am not the kind of person who...\"": "İçinde taşıdığın bir şüpheyi düşün. \"Yapamam\" veya \"Ben ... yapacak biri değilim\" diye başlayan bir cümle.",
  "Bring your attention to the top of your head. Let the scalp soften. Let the forehead smooth out.": "Dikkatini başının tepesine getir. Saçlı derin gevşesin. Alnın yumuşasın.",
