  "Dream Dollars (D$) are symbolic simulation tokens that cannot be purchased, gambled, or withdrawn. They act as a behavioral mirror for where your daily energy is invested.": "Hayal Doları (D$), satın alınamayan, kumarda kullanılamayan veya çekilemeyen sembolik simülasyon birimleridir. Günlük enerjini nereye harcadığını gösteren davranışsal bir ayna görevi görür.",
  "Dream Dollars (D$) has no cash value and cannot be withdrawn. All purchases are symbolic representations in your lifestyle blueprint.": "Hayal Dolarının (D$) nakit değeri yoktur ve çekilemez. Tüm satın alımlar yaşam planındaki sembolik temsillerdir.",
  "Dream Dollars (D$) is a simulation currency. Purchases and assets in My Future Life represent symbolic milestones.": "Hayal Doları (D$) bir simülasyon para birimidir. Gelecekteki Hayatım'daki satın alımlar ve varlıklar sembolik dönüm noktalarını temsil eder.",
  "Dream Dollars (D$) is a virtual simulation economy with no cash value. Purchases and allocations are symbolic representations of your life design.": "Hayal Doları (D$) nakit değeri olmayan sanal bir simülasyon ekonomisidir. Satın alımlar ve dağılımlar, yaşam tasarımının sembolik temsilleridir.",
  "Dream Dollars is a virtual simulation currency designed to anchor focus. It cannot be purchased, transferred, or exchanged for fiat currency.": "Hayal Doları, odağı güçlendirmek için tasarlanmış sanal bir simülasyon para birimidir. Satın alınamaz, devredilemez veya gerçek paraya çevrilemez.",
  "Dream Dollars is a virtual simulation economy with no cash value. Purchases and allocations are symbolic.": "Hayal Doları, nakit değeri olmayan sanal bir simülasyon ekonomisidir. Satın alımlar ve dağılımlar semboliktir.",
