  "Every Dream Dollar is a vote. Cast the first one before breakfast.": "Her Hayal Doları bir oydur. İlkini kahvaltıdan önce ver.",
  "Every completed mission deposits D$ into your ledger in the Dream Bank. No fake math, no pay-to-win mechanics, and anti-binge caps.": "Tamamlanan her görev, Hayal Bankası hesabına D$ yatırır. Yanıltıcı hesap yok, ödeyerek kazanma yok; aşırı kullanımı sınırlayan tavanlar var.",
  "Every completed mission is a non-negotiable vote cast directly for the reality of {dName}.": "Tamamlanan her görev, {dName} gerçeği için doğrudan verilmiş tavizsiz bir oydur.",
  "Every completed mission is a symbolic vote for the life you are building.": "Tamamlanan her görev, inşa ettiğin hayat için sembolik bir oydur.",
  "Every curated home, car, watch, journey and experience — browse like a shop, choose like a builder.": "Özenle seçilmiş her ev, otomobil, saat, yolculuk ve deneyim — mağaza gezer gibi keşfet, hayatını inşa eden biri gibi seç.",
  "Every disciplined decision today anchors {dName} from an abstract dream into an impending reality.": "Bugünkü her disiplinli karar, {dName} hayalini soyut bir düşünceden yaklaşan bir gerçeğe dönüştürür.",
  "Every second you stay here, doing nothing, you are building tolerance for boredom. That is strength.": "Hiçbir şey yapmadan burada kaldığın her saniye, sıkılmaya dayanıklılığını artırıyorsun. Bu bir güçtür.",
  "Every temptation resisted is an immediate deposit into the reality of your future self.": "Direndiğin her cazibe, gelecekteki benliğinin gerçeğine anında yapılan bir yatırımdır.",
  "Every unfinished project, unanswered proposal, and lingering decision drains working memory. Killing or shipping an idea restores vitality.": "Bitmemiş her proje, yanıtsız teklif ve bekleyen karar çalışma belleğini tüketir. Bir fikri bitirmek veya bırakmak canlılığı geri getirir.",
  "Examine Two Futures": "İki Geleceği İncele",
