  "Fear Then Freedom": "Önce Korku, Sonra Özgürlük",
  "Fear is a poor long-term fuel, but a clear picture of the default path is a superb compass. Make it concrete, count what it costs, and notice the small moments you drift toward it.": "Korku uzun vadede iyi bir yakıt değildir; ama akışına bıraktığın yolun net resmi güçlü bir pusuladır. Somutlaştır, bedelini hesapla ve ona doğru sürüklendiğin küçük anları fark et.",
  "Fear of putting out work and having it meet total silence.": "Ortaya bir iş koyup tam bir sessizlikle karşılaşma korkusu.",
  "Feature it in your Daily Vision Affirmations on the Home page and on your Vision Board.": "Ana sayfadaki Günlük Vizyon Olumlamalarında ve Vizyon Panonda öne çıkar.",
  "Featured Curations": "Öne Çıkan Seçkiler",
  "Feedback & Iteration": "Geri Bildirim ve İyileştirme",
  "Feel Good": "İyi Hisset",
  "Feel a quiet strength in your chest. Confidence is not loud. It is calm.": "Göğsünde sessiz bir güç hisset. Özgüven gürültülü değildir. Sakindir.",
  "Feel a steady strength rising from the ground, up through your legs, into your spine. Quiet. Certain.": "Yerden yükselip bacaklarından omurgana ulaşan sağlam bir güç hisset. Sessiz. Kesin.",
  "Feel energy building in your chest. A warm pressure. That is your drive. It was never gone, only buried.": "Göğsünde biriken enerjiyi hisset. Sıcak bir basınç. Bu senin itici gücün. Hiç kaybolmadı, yalnızca üstü örtüldü.",
  "Feel it in your hands. They want to work. Feel it in your legs. They want to stand.": "Ellerinde hisset. Çalışmak istiyorlar. Bacaklarında hisset. Ayağa kalkmak istiyorlar.",
  "Feel the corners of your mouth lift a little more. Your body believes what you show it.": "Dudaklarının köşelerinin biraz daha yükseldiğini hisset. Bedenin ona gösterdiğine inanır.",
  "Feel the warmth in your chest expanding. Gratitude is not a thought. It is a feeling in the body.": "Göğsündeki sıcaklığın yayıldığını hisset. Minnettarlık bir düşünce değildir. Bedende bir histir.",
  "Feel the weight of that evidence. You are not pretending. You are remembering.": "Bu kanıtın ağırlığını hisset. Rol yapmıyorsun. Hatırlıyorsun.",
  "Feel this future in your body now. It is not a wish. It is a memory of something coming.": "Bu geleceği şimdi bedeninde hisset. Bu bir dilek değil. Yaklaşan bir şeyin anısı.",
  "Feel your attention narrowing, like a lens coming into focus. Sharp. Bright. Still.": "Dikkatinin netleşen bir mercek gibi daraldığını hisset. Keskin. Aydınlık. Dingin.",
  "Feel your eyes growing heavier. Your face softening. Your jaw releasing.": "Gözlerinin ağırlaştığını hisset. Yüzünün yumuşadığını. Çenenin gevşediğini.",
  "Feel your finances. Calm. Enough. Growing. Money is a tool in your hands, not a weight on your chest.": "Maddi durumunu hisset. Sakin. Yeterli. Büyüyor. Para göğsünde bir yük değil, elinde bir araç.",
  "Feel your shoulders drop away from your ears. Let them become heavy.": "Omuzlarının kulaklarından uzaklaştığını hisset. Ağırlaşmalarına izin ver.",
  "Feel-Good Boost": "İyi Hissetme Desteği",
  "Fell short due to unexpected emergency schedule conflict.": "Beklenmedik acil bir program çakışması nedeniyle tamamlanamadı.",
