  "I am building a life where I do deep work with calm focus, achieve complete financial autonomy, and show up fully for the people I care about.": "Sakin bir odakla derin çalıştığım, tam finansal özgürlüğe ulaştığım ve sevdiklerimin yanında bütünüyle olduğum bir hayat inşa ediyorum.",
  "I am building a life where...": "Öyle bir hayat inşa ediyorum ki...",
  "I am someone who finishes important work, protects my attention, and acts before I feel ready.": "Önemli işleri bitiren, dikkatini koruyan ve hazır hissetmeden harekete geçen biriyim.",
  "I just unlocked \"{name}\" in my simulation through daily completed missions on One Decision Away.": "One Decision Away'de her gün tamamladığım görevlerle simülasyonumda \"{name}\" kilidini açtım.",
  "I refuse to become someone who leaves their best ideas in notes and lets distraction decide their life.": "En iyi fikirlerini notlarda bırakan ve hayatını dikkat dağıtıcıların belirlemesine izin veren biri olmayı reddediyorum.",
  "I refuse to become someone who leaves their best potential in draft notes and lets distraction decide their fate.": "En yüksek potansiyelini taslak notlarda bırakan ve kaderini dikkat dağıtıcıların belirlemesine izin veren biri olmayı reddediyorum.",
  "I refuse to become someone who...": "Şöyle biri olmayı reddediyorum...",
