  "Iconic all-terrain luxury fortress featuring handcrafted diamond-stitched leather, side-pipe exhaust rumble, and triple locking differentials.": "El işçiliği baklava dikişli deri, yan egzoz gürültüsü ve üçlü diferansiyel kilidiyle her araziye uygun ikonik lüks kale.",
  "Ideas Room": "Fikir Odası",
  "Identify the one compromise you made yesterday that your Future Self would never accept. Refuse to repeat it today.": "Dün verdiğin ve Gelecekteki Benliğinin asla kabul etmeyeceği tek tavizi belirle. Bugün tekrarlamayı reddet.",
  "Identify the one task you have delayed 3 times this week. Execute its next concrete step before opening your inbox.": "Bu hafta 3 kez ertelediğin işi belirle. Gelen kutunu açmadan önce sıradaki somut adımını at.",
  "Identity & Sovereignty": "Kimlik ve Özgürlük",
  "Identity Expansion": "Kimliğin Genişlemesi",
  "Identity Labels to Release (1 per line)": "Bırakılacak Kimlik Etiketleri (her satıra 1)",
  "Identity is demonstrated through action in real-time, not through philosophical intentions.": "Kimlik, felsefi niyetlerle değil, o anda yaptığın eylemlerle ortaya konur.",
  "Identity shift precedes behavioural change. Define who you are becoming and what you leave behind.": "Kimlik değişimi davranış değişiminden önce gelir. Kime dönüştüğünü ve neleri geride bıraktığını tanımla.",
  "Identity statement": "Kimlik bildirisi",
  "Identity to release": "Geride bırakılacak kimlik",
  "If Nothing Changes — Timeline": "Hiçbir Şey Değişmezse — Zaman Çizelgesi",
  "If a thought appears, let it drift past like a cloud, and return to the feeling of the breath.": "Bir düşünce belirse, bulut gibi geçip gitmesine izin ver ve nefesinin hissine dön.",
  "If distractions come, you will write them down and return. You do not chase them.": "Dikkat dağıtıcılar gelirse onları yazıp geri döneceksin. Peşlerine düşmeyeceksin.",
  "If nothing changes, describe an ordinary Tuesday five years from now — wake-up to lights-out.": "Hiçbir şey değişmezse beş yıl sonraki sıradan bir salıyı anlat — uyanıştan yatışa kadar.",
  "If nothing changes, describe an ordinary Tuesday five years from now.": "Hiçbir şey değişmezse beş yıl sonraki sıradan bir salıyı anlat.",
  "If something went wrong, let it be. Tomorrow is a new chance. Tonight, you rest.": "Bir şey ters gittiyse bırak öyle kalsın. Yarın yeni bir şans. Bu gece dinleniyorsun.",
  "If the One Decision isn't done, this is the hour. 25 minutes, phone away.": "Tek Karar henüz tamamlanmadıysa zamanı şimdi. 25 dakika, telefon uzakta.",
  "If you want to go fast, go alone. If you want to go far, go together with clear vision and uncompromising standards.": "Hızlı gitmek istiyorsan yalnız git. Uzağa gitmek istiyorsan net bir vizyon ve tavizsiz standartlarla birlikte git.",
