  "Imagine a door in front of you. On the other side is your life, three years from now, if you keep choosing well.": "Önünde bir kapı hayal et. Diğer tarafında, iyi seçimler yapmayı sürdürürsen üç yıl sonra yaşayacağın hayat var.",
  "Imagine a road splitting in two. Take the left path first. This is the road where nothing changes.": "İkiye ayrılan bir yol hayal et. Önce soldan git. Hiçbir şeyin değişmediği yol bu.",
  "Imagine the feeling of finishing it. That quiet, deep satisfaction. That is real reward.": "Bitirdiğindeki hissi hayal et. O sessiz, derin tatmini. Gerçek ödül budur.",
