  "Not completed": "Tamamlanmadı",
  "Not connected to a cloud project yet. To enable sync, create a free Supabase project, run": "Henüz bir bulut projesine bağlı değil. Eşitlemeyi açmak için ücretsiz bir Supabase projesi oluştur ve çalıştır",
  "Not for Sale": "Satılık Değil",
  "Not having given my true ideas a dedicated year of consistent focus.": "Gerçek fikirlerime bir yıl boyunca istikrarlı odak ayırmamış olmak.",
  "Not now": "Şimdi değil",
  "Not supported here": "Burada desteklenmiyor",
  "Not today": "Bugün değil",
  "Note (Optional)": "Not (İsteğe Bağlı)",
  "Note:": "Not:",
  "Nothing found to archive.": "Arşivlenecek bir şey bulunamadı.",
  "Notice any restlessness in your body. The urge to check, to scroll, to reach for something. Just notice it.": "Bedenindeki huzursuzluğu fark et. Kontrol etme, kaydırma, bir şeye uzanma isteğini. Yalnızca fark et.",
  "Notice how they hold their shoulders. Their eyes. The pace of their words. Feel it in your own body now.": "Omuzlarını nasıl tuttuklarını fark et. Gözlerini. Konuşmalarının hızını. Şimdi bunu kendi bedeninde hisset.",
  "Notice the home you live in. Walk through it slowly. Touch the surfaces. Feel how it feels to be here.": "Yaşadığın evi fark et. İçinde yavaşça yürü. Yüzeylere dokun. Burada olmanın hissini duy.",
  "Notice where that doubt lives in your body. A tightness. A heaviness. Just locate it.": "Bu şüphenin bedeninde nerede yaşadığını fark et. Bir sıkışma. Bir ağırlık. Yalnızca yerini bul.",
  "Notice your body. How do you carry yourself? How do you move, breathe, stand?": "Bedenini fark et. Nasıl bir duruşun var? Nasıl hareket ediyor, nefes alıyor, ayakta duruyorsun?",
  "Notice: nothing outside you changed. Only what you looked at. This is a superpower.": "Fark et: dışarıda hiçbir şey değişmedi. Yalnızca baktığın şey değişti. Bu bir süper güç.",
  "Notice: the urge is already softer. You are stronger than the pull.": "Fark et: dürtü şimdiden yumuşadı. Sen onun çekiminden güçlüsün.",
  "Noticed {n} resistance thoughts.": "{n} direnç düşüncesi fark edildi.",
  "Notification permission granted.": "Bildirim izni verildi.",
  "Notifications are blocked in the browser. Allow them to receive nudges.": "Tarayıcı bildirimleri engelliyor. Hatırlatmaları almak için izin ver.",
  "Now": "Şimdi",
  "Now find your future self in this life. Look into their eyes. They are calm, clear, and proud of you.": "Şimdi bu hayatta gelecekteki benliğini bul. Gözlerine bak. Sakin, net ve seninle gurur duyuyor.",
  "Now it is three years. The projects you were going to start are still ideas. Notice what you stopped mentioning to people.": "Şimdi üç yıl geçti. Başlayacağın projeler hâlâ fikir olarak duruyor. İnsanlara artık nelerden söz etmediğini fark et.",
  "Now name your one task. Only one. Say it silently, clearly, as a single sentence.": "Şimdi tek işini adlandır. Yalnızca bir tane. İçinden, netçe, tek bir cümleyle söyle.",
  "Now recognize: this is not truth. It is a story. Someone, or something, taught it to you.": "Şimdi fark et: bu gerçek değil. Bir hikâye. Biri veya bir şey sana bunu öğretti.",
  "Now simply rest in this stillness. Nothing to fix. Nothing to chase. Just breathing.": "Şimdi bu dinginlikte dinlen. Düzeltecek bir şey yok. Peşinden koşacak bir şey yok. Yalnızca nefes.",
  "Now think of something small from today. A taste. A sound. A moment of comfort. Thank it.": "Şimdi bugünden küçük bir şey düşün. Bir tat. Bir ses. Rahat hissettiğin bir an. Ona teşekkür et.",
  "Now turn around. Walk back to the fork. Feel each step getting lighter.": "Şimdi dön. Yol ayrımına geri yürü. Her adımının hafiflediğini hisset.",
  "Now, from this place, look back at today. What is the one decision that moved you onto this road?": "Şimdi buradan bugüne bak. Seni bu yola taşıyan tek karar neydi?",
  "Now, why are you doing this? Not the small reason. The real one. Who are you becoming? Who are you doing it for?": "Peki bunu neden yapıyorsun? Küçük nedeni değil. Gerçek olanı. Kime dönüşüyorsun? Kimin için yapıyorsun?",
