  "One brave email. One hard workout. One honest page. Pick one.": "Cesur bir e-posta. Zorlu bir antrenman. Dürüst bir sayfa. Birini seç.",
  "One by one, place each paper in a drawer. It will still be there later. Right now, it is closed.": "Her kâğıdı tek tek çekmeceye koy. Sonra yine orada olacak. Şu an kapalı.",
