  "One meaningful action a day is how the future gets built. Pick it now, before the day picks for you.": "Gelecek, her gün anlamlı bir eylemle inşa edilir. Gün senin yerine seçmeden şimdi sen seç.",
  "One month bespoke private navigation along French & Italian Rivieras with onboard private chef, Seabobs, and secluded anchorage.": "Fransız ve İtalyan Rivieralarında bir ay kişiye özel seyir; teknede özel şef, Seabob’lar ve sakin demirleme yerleri.",
  "One night you'll describe for the rest of your life.": "Hayatın boyunca anlatacağın bir gece.",
  "One row per completion date with habit title, category, linked life goal, and streak at completion.": "Her tamamlama tarihi için alışkanlık başlığı, kategori, bağlı yaşam hedefi ve tamamlama anındaki seriyi içeren bir satır.",
  "One row per micro-habit with lifetime completions, active streak, best streak, and linked goals.": "Her mikro alışkanlık için toplam tamamlamalar, etkin seri, en iyi seri ve bağlı hedefleri içeren bir satır.",
