  "Say no to one low-value impulse today to protect your deep work hours.": "Derin çalışma saatlerini korumak için bugün düşük değerli bir dürtüye hayır de.",
  "Say no to one thing this afternoon so you can say yes to the thing that matters.": "Önemli olana evet diyebilmek için bu öğleden sonra bir şeye hayır de.",
  "Say silently: For the next session, this is the only thing that exists.": "İçinden söyle: Önümüzdeki oturum boyunca var olan tek şey bu.",
  "Say silently: I am allowed to feel good today. I do not have to earn it. It is already mine.": "İçinden söyle: Bugün iyi hissetmeme izin var. Bunu hak etmek için uğraşmak zorunda değilim. Zaten benim.",
  "Say silently: I am becoming this person, one decision at a time.": "İçinden söyle: Her kararla bu kişiye dönüşüyorum.",
  "Say silently: I did enough today. I am allowed to stop now.": "İçinden söyle: Bugün yeterince yaptım. Artık durabilirim.",
  "Say silently: I do not need permission. I do not need approval. I am already enough.": "İçinden söyle: İzne ihtiyacım yok. Onaya ihtiyacım yok. Zaten yeterliyim.",
  "Say silently: I do not wait to feel ready. I act, and readiness follows.": "İçinden söyle: Hazır hissetmeyi beklemiyorum. Harekete geçiyorum, hazır olma hali ardından geliyor.",
  "Say silently: I have enough. I am enough. And more is on its way.": "İçinden söyle: Yeterince şeye sahibim. Ben yeterliyim. Ve daha fazlası yolda.",
  "Say silently: I have proof. I have done hard things before. I will do them again.": "İçinden söyle: Kanıtım var. Daha önce zor şeyler yaptım. Yine yapacağım.",
  "Say silently: I see you. I understand how I got here. And I refuse to stay.": "İçinden söyle: Seni görüyorum. Buraya nasıl geldiğimi anlıyorum. Ve burada kalmayı reddediyorum.",
  "Say silently: I speak clearly. I decide quickly. I keep my standards, even when no one is watching.": "İçinden söyle: Açık konuşurum. Hızlı karar veririm. Kimse görmese de standartlarımı korurum.",
  "Say silently: I trust myself. I keep my word to myself. What I decide, I do.": "İçinden söyle: Kendime güveniyorum. Kendime verdiğim sözü tutuyorum. Karar verdiğimi yapıyorum.",
  "Say silently: Today I move. Today I build. Today is one decision away from a different life.": "İçinden söyle: Bugün harekete geçiyorum. Bugün inşa ediyorum. Bugün farklı bir hayata bir karar uzaktayım.",
