  "Settle in. Let your shoulders soften and let a small smile rest on your lips, even if it feels silly.": "Yerleş. Omuzların gevşesin ve biraz tuhaf gelse bile dudaklarında küçük bir gülümseme belirsin.",
  "Settles the restless urge for quick hits and re-anchors your reward system to meaningful action.": "Hızlı ödül arayışının huzursuz dürtüsünü yatıştırır ve ödül sistemini yeniden anlamlı eyleme bağlar.",
  "Settling in… the guide will begin in a moment.": "Yerleşiyorsun… rehber birazdan başlayacak.",
  "Seven Mornings": "Yedi Sabah",
  "Seven days of guided physical conditioning, biomarker diagnostics, thermal mineral baths, and circadian reset in the Swiss Alps.": "İsviçre Alpleri'nde yedi gün rehberli fiziksel kondisyon, biyobelirteç analizi, termal mineral banyoları ve sirkadiyen ritmi yeniden düzenleme.",
  "Seven mornings in the water with a coach, sunset sessions, and a body that feels ten years younger.": "Bir eğitmenle suda yedi sabah, gün batımı seansları ve kendini on yaş genç hisseden bir beden.",
  "Seven nights in an overwater villa with a glass floor, private pool and a butler who remembers your coffee.": "Cam zeminli, özel havuzlu ve kahveni hatırlayan bir uşakla su üstü villada yedi gece.",
