  "Singapore Sky Garden Penthouse": "Singapore Gökyüzü Bahçeli Çatı Dairesi",
  "Singing bowls and temple gong tones anchor the mind firmly in the present moment.": "Ses kaseleri ve tapınak gonglarının tonları zihni şimdiki ana sağlamca bağlar.",
  "Single Story": "Tek Katlı",
  "Single-story modernist villa where every room opens onto a mirror-still pool and Mediterranean garden.": "Her odası ayna gibi durgun bir havuza ve Akdeniz bahçesine açılan tek katlı modernist villa.",
  "Single-tasking": "Tek işe odaklanma",
  "Sit as if you are already the person you are becoming. Notice how the posture changes on its own.": "Dönüşmekte olduğun kişi zaten senmişsin gibi otur. Duruşunun kendiliğinden nasıl değiştiğini fark et.",
  "Sit at your workspace. Close your eyes. In six minutes you will begin the most important work of your day.": "Çalışma alanına otur. Gözlerini kapat. Altı dakika sonra gününün en önemli işine başlayacaksın.",
  "Sit comfortably and close your eyes. In this session, you will visit the life you are building.": "Rahatça otur ve gözlerini kapat. Bu oturumda inşa ettiğin hayatı ziyaret edeceksin.",
  "Sit down and close your eyes. This walk has two halves. The first one is not comfortable, and that is the point.": "Otur ve gözlerini kapat. Bu yürüyüşün iki yarısı var. İlki rahat değil; zaten amaç da bu.",
  "Sit up straight. Spine tall. Chin level. This session is not for resting. It is for igniting.": "Dik otur. Omurgan uzasın. Çenen yere paralel olsun. Bu oturum dinlenmek için değil. İçindeki ateşi yakmak için.",
  "Sit with the stillness. Let your baseline come back up. You are recalibrating.": "Dinginliğin içinde kal. Doğal seviyen yeniden yükselsin. Kendini yeniden ayarlıyorsun.",
  "Six Seats": "Altı Koltuk",
  "Six full months of living expenses untouched in liquid reserves, giving complete autonomy over career choices.": "Kariyer seçimlerinde tam bağımsızlık sağlayan, likit rezervlerde dokunulmadan duran altı aylık yaşam gideri.",
  "Sixty seconds of freefall from 4,000 m — fear, then the widest view of your life.": "4.000 metreden altmış saniye serbest düşüş — önce korku, sonra hayatının en geniş manzarası.",
  "Skeletonized Calibre 3132": "İskeletleştirilmiş Kalibre 3132",
  "Skeletonized slate-grey dial revealing the patented double balance wheel mechanism in stainless steel with hand-finished bevels.": "Elle işlenmiş pahları olan paslanmaz çelik yapıda patentli çift balans mekanizmasını gösteren arduvaz grisi iskelet kadran.",
