  "Ski-in chalet in old larch with a slate spa, fireplace lounge and a boot room that smells of pine.": "Eski karaçamdan yapılmış; arduvaz spası, şömineli salonu ve çam kokan bot odasıyla kayakla girilen dağ evi.",
