  "Systematically fund dream purchases and eliminate consumer impulse spending.": "Hayal alışverişlerini düzenli olarak finanse et ve dürtüsel tüketim harcamalarını ortadan kaldır.",
  "THE LIFE YOU'RE ALLOWING (ANTI-VISION)": "İZİN VERDİĞİN HAYAT (KARŞI VİZYON)",
