  "Tailoring": "Terzilik",
  "Take / Add Photo": "Fotoğraf Çek / Ekle",
  "Take 3 deliberate deep breaths before diving into your next focus block.": "Bir sonraki odak bloğuna başlamadan önce bilinçli 3 derin nefes al.",
  "Take Photo": "Fotoğraf Çek",
  "Take Photo with Camera": "Kamerayla Fotoğraf Çek",
  "Take Snapshot": "Anlık Görüntü Al",
  "Take Your Own Photo": "Kendi Fotoğrafını Çek",
  "Take a boat-handling course and rent one for a weekend.": "Tekne kullanım kursuna katıl ve bir hafta sonu için tekne kirala.",
  "Take a deep breath. Open your eyes. Now write down the one decision your future self gave you.": "Derin bir nefes al. Gözlerini aç. Şimdi gelecekteki halinin sana verdiği tek kararı yaz.",
  "Take a deep, grateful breath. Hold the feeling.": "Derin ve şükran dolu bir nefes al. Bu hissi koru.",
  "Take a full breath. When you open your eyes, choose one real action instead of one more scroll.": "Dolu bir nefes al. Gözlerini açtığında bir kez daha ekranı kaydırmak yerine gerçek bir eylem seç.",
  "Take a photo from your camera and jot down your mental state, execution win, or vision reflection.": "Kameranla bir fotoğraf çek ve ruh halini, eylem başarını veya vizyonuna dair düşünceni not et.",
  "Take a slow breath in through your nose... and let it out through your mouth, like a long sigh.": "Burnundan yavaşça nefes al... ve uzun bir iç çekiş gibi ağzından bırak.",
  "Take a two-week Paris stay in the 7th and test the daily rhythm.": "Paris'in 7. bölgesinde iki hafta kal ve günlük ritmi dene.",
  "Take one concrete physical step toward this milestone before the day concludes.": "Gün bitmeden bu dönüm noktasına doğru somut bir fiziksel adım at.",
  "Take one deep breath. Open your eyes. Go set it, and go do it.": "Derin bir nefes al. Gözlerini aç. Git, kararını belirle ve uygula.",
  "Take one deep, grateful breath. Let it out with a smile.": "Derin ve şükran dolu bir nefes al. Gülümseyerek bırak.",
  "Take one deeper breath. When you are ready, gently open your eyes, carrying this calm with you.": "Biraz daha derin nefes al. Hazır olduğunda gözlerini nazikçe aç ve bu sakinliği yanında taşı.",
  "Take one strong breath in. Let it out slowly.": "Güçlü bir nefes al. Yavaşça bırak.",
  "Take photo": "Fotoğraf çek",
  "Take the Lofoten road trip and shortlist a village.": "Lofoten yolculuğuna çık ve bir köy seç.",
  "Take the first 2-minute step on what you have been overthinking.": "Fazla düşündüğün konuda ilk 2 dakikalık adımı at.",
  "Take the right path. This is the road where you kept your word to yourself.": "Sağdaki yolu seç. Bu, kendine verdiğin sözü tuttuğun yol.",
  "Take the train — no car needed.": "Trene bin — arabaya gerek yok.",
  "Take three sharp breaths in through the nose, and out through the mouth. Wake the body up.": "Burundan alıp ağızdan vererek üç canlı nefes al. Bedeni uyandır.",
  "Talk to a yacht broker about fractional and charter income.": "Bir yat aracısıyla ortak mülkiyet ve kiralama gelirleri hakkında konuş.",
  "Tandem Skydive": "Tandem Paraşüt Atlayışı",
  "Tanzania": "Tanzania",
  "Tap Chime": "Dokunuş Çanı",
  "Tap any habit below to mark it done for today.": "Bugün tamamlandı olarak işaretlemek için aşağıdaki alışkanlıklardan birine dokun.",
  "Tap the moment you catch yourself sliding. Each tap is one honest vote for the default future — and noticing it is the first vote back.": "Kendini kayarken fark ettiğin anda dokun. Her dokunuş Akışına Bırakılan Geleceğe verilmiş dürüst bir oy — ve bunu fark etmek geri dönüşün ilk oyu.",
