  "Turn decisive daily action into Dream Dollars, furnish your future life in a symbolic economy, and connect every dream to an actionable real-world bridge.": "Kararlı günlük eylemlerini Hayal Doları'na dönüştür, sembolik bir ekonomide gelecekteki hayatını kur ve her hayalini gerçek dünyada uygulanabilir bir köprüye bağla.",
  "Turn meaningful life projects into structured daily quests, deep-work focus sprints, and boss fights.": "Anlamlı yaşam projelerini düzenli günlük görevlere, derin çalışma seanslarına ve büyük mücadelelere dönüştür.",
  "Turn the inner weather to sunshine": "İç dünyanda güneş açsın",
